import sys,math,numpy as np
sys.path.insert(0,'/app/output');from gen import load_components
for bounddeg in [110,120,130]:
 print('BOUND',bounddeg)
 lo,hi=-math.radians(bounddeg),math.radians(bounddeg)
 for j,c in enumerate(load_components()):
  p=c['route_px'];w=c['width_mm']; opts=[]
  for i,(du,dv) in enumerate(np.diff(p,axis=0)):
   phi=math.atan2(-du,-dv);ww=np.clip((w[i]+w[i+1])/2,.4,4);al=math.asin(float(np.clip((ww-.4)/3.6,0,1)))
   vals=[]
   for raw in [phi+math.pi/2-al,phi+math.pi/2+al]:
    for k in range(-3,4):
     a=raw+k*math.pi
     if lo<=a<=hi and not any(abs(a-b)<1e-8 for b in vals):vals.append(a)
   opts.append(sorted(vals))
  # DP
  costs=np.array([a*a*.02 for a in opts[0]]); backs=[]
  for i in range(1,len(opts)):
   nc=[];nb=[]
   for a in opts[i]:
    vals=costs+np.array([(a-b)**2 for b in opts[i-1]])+0.02*a*a
    k=int(vals.argmin()); nc.append(vals[k]);nb.append(k)
   costs=np.array(nc);backs.append(nb)
  k=int(costs.argmin());yaws=[opts[-1][k]]
  for i in range(len(backs)-1,-1,-1):k=backs[i][k];yaws.append(opts[i][k])
  y=np.array(yaws[::-1]);d=np.abs(np.diff(y));
  print(j,'range',np.round(np.rad2deg([y.min(),y.max()]),1),'maxstep',round(np.rad2deg(d.max()),1),'steps>45',sum(d>math.radians(45)),'empty',sum(not o for o in opts))
